-- Quranically V1.7: targeted source-grounded Qur’anic themes and Sunnah reference dossiers.
-- Exact references; no unattributed Tafsir or individualized jurisprudence. Scholarly review pending.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('patience-quranic-theme','patience-quranic-theme','Patience (Sabr) in the Qur’an','الصبر في القرآن','Scriptural themes of patience, prayer and hardship','quranic_themes','concept','The Qur’an repeatedly discusses sabr, including 2:153, which connects patience with prayer, and 94:5–6, which pairs hardship with ease. Patience is presented as an active religious virtue rather than indifference to injustice or an excuse to delay medical or personal protection.','Primary-source-linked introductory encyclopedia dossier.','patience,sabr,quran patience,what does quran say about patience,patience in islam,steadfastness,patient with hardship','Independent qualified Tafsir/Hadith scholarly review pending.','editorial_draft','published','90');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('patience-quranic-theme-s1','patience-quranic-theme','The Qur’anic foundation','scripture','Surah Al-Baqarah 2:153 connects patience with prayer and seeking help from Allah. Its message is directed to believers and is meant to be read within the wider discussion of faith, obligations and hardship, not as a formula promising that every difficulty ends immediately.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('patience-quranic-theme-s2','patience-quranic-theme','Hardship and hope','scripture','Surah Ash-Sharh 94:5–6 repeats the teaching that ease is associated with hardship. The verses encourage hope and perseverance. This brief overview does not claim to resolve every exegetical detail about timing, number or the nature of relief.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('patience-quranic-theme-s3','patience-quranic-theme','Practical moral application','practice','Patience may involve steady ethical action, continuing responsibilities, prayer, avoiding cruelty and seeking legitimate solutions to problems. These examples are editorial applications of broad Qur’anic themes rather than a quotation of a single verse. Being patient does not mean tolerating abuse or refusing appropriate care.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('patience-quranic-theme-s4','patience-quranic-theme','Limits of this overview','methodology','Scholarly Tafsir distinguishes contexts and explanations of different patience verses. Quranically links the exact sources but has not authenticated a comprehensive Tafsir synthesis of the topic; a fuller comparative explanation requires independent scholar review.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('patience-quranic-theme-r1','patience-quranic-theme','quran','The Qur’an — Al-Baqarah','2:153','https://quran.com/2/153','Primary source pointer; scholarly interpretation pending','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('patience-quranic-theme-r2','patience-quranic-theme','quran','The Qur’an — Ash-Sharh','94:5','https://quran.com/94/5','Primary source pointer; scholarly interpretation pending','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('patience-quranic-theme-r3','patience-quranic-theme','quran','The Qur’an — Ash-Sharh','94:6','https://quran.com/94/6','Primary source pointer; scholarly interpretation pending','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('riba-in-quranic-text','riba-in-quranic-text','Riba in the Qur’an: Text and Interpretation Boundaries','الربا في القرآن','Direct verses and financial interpretation limits','quranic_themes','concept','Qur’an 2:275 distinguishes trade from riba and condemns riba, while 2:278 calls believers to leave outstanding riba. Applying those teachings to a specific modern mortgage, business instrument or bank product requires qualified jurisprudential and financial review; this source-led introduction does not deliver an individual fatwa.','Primary-source-linked introductory encyclopedia dossier.','riba,usury,interest in quran,does quran discuss riba,quran riba,interest and islam,interest forbidden,prohibition of riba,bank interest','Independent qualified Tafsir/Hadith scholarly review pending.','editorial_draft','published','91');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('riba-in-quranic-text-s1','riba-in-quranic-text','A direct Qur’anic distinction','scripture','Surah Al-Baqarah 2:275 expressly distinguishes permitted trade from riba and addresses its prohibition. It is a core primary source for Islamic discussions of financial dealings. The meaning and boundaries of transactions require careful juristic application.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('riba-in-quranic-text-s2','riba-in-quranic-text','The call to desist','scripture','Surah Al-Baqarah 2:278 addresses believers about relinquishing what remains of riba. The following verse, 2:279, addresses principal amounts and avoidance of harm. These verses should be read together in context rather than used as a substitute for a financial contract review.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('riba-in-quranic-text-s3','riba-in-quranic-text','Questions about contemporary finance','interpretation','Financial questions today may involve different contracts, loans, interest-based obligations, investments and currencies. Whether a specific product meets or violates Islamic financial rules cannot be reliably determined merely by matching a keyword in an English translation. A qualified scholar familiar with the exact contract and jurisdiction should assess the situation.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('riba-in-quranic-text-s4','riba-in-quranic-text','What this source dossier does not decide','methodology','This entry presents verified verse references and a broad introductory distinction only. It does not determine whether any specific mortgage, financial service, savings product or business arrangement is permissible, nor does it replace an independently authenticated Tafsir or legal ruling.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('riba-in-quranic-text-r1','riba-in-quranic-text','quran','The Qur’an — Al-Baqarah','2:275','https://quran.com/2/275','Primary source pointer; scholarly interpretation pending','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('riba-in-quranic-text-r2','riba-in-quranic-text','quran','The Qur’an — Al-Baqarah','2:278','https://quran.com/2/278','Primary source pointer; scholarly interpretation pending','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('riba-in-quranic-text-r3','riba-in-quranic-text','quran','The Qur’an — Al-Baqarah','2:279','https://quran.com/2/279','Primary source pointer; scholarly interpretation pending','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('maryam-in-quran','maryam-in-quran','Maryam in the Qur’an: A Primary-Source Introduction','مريم في القرآن','Selected Qur’anic passages about Maryam','quranic_themes','concept','Maryam is named in Qur’an 19:16, and Qur’an 3:42 describes her being chosen and purified. Qur’an 66:12 also refers to her devotion. These passages anchor an introduction to Maryam’s place in the Qur’an, while full narrative chronology and Tafsir require further qualified interpretation.','Primary-source-linked introductory encyclopedia dossier.','maryam,mary,mariam,where is maryam mentioned,maryam in quran,surah maryam,mary mother of isa,mary in islam','Independent qualified Tafsir/Hadith scholarly review pending.','editorial_draft','published','92');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('maryam-in-quran-s1','maryam-in-quran','Maryam in the named Surah','scripture','Surah Maryam 19:16 introduces Maryam and her withdrawal from her family to an eastern place. The surrounding verses provide the narrative context and should be read together rather than reducing the account to an isolated phrase.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('maryam-in-quran-s2','maryam-in-quran','Her standing in the Qur’an','scripture','Surah Ali Imran 3:42 states that Maryam was chosen and purified. The verse is a primary basis for understanding her significance in Islamic scripture. Detailed theological interpretation belongs within Tafsir and should not be invented from a short translation.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('maryam-in-quran-s3','maryam-in-quran','A further Qur’anic example','scripture','Surah At-Tahrim 66:12 presents Maryam as an example of devotion and belief. The passage connects her story to faith and worship, and its meaning is best understood alongside the surrounding context.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('maryam-in-quran-s4','maryam-in-quran','What remains for a full study','methodology','A complete study would connect the verses of Surahs Maryam, Ali Imran and At-Tahrim, compare reliable Tafsir traditions and distinguish scriptural narrative from later retellings. This introductory article gives original verse references and does not purport to settle theological debates.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('maryam-in-quran-r1','maryam-in-quran','quran','The Qur’an — Maryam','19:16','https://quran.com/19/16','Primary source pointer; scholarly interpretation pending','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('maryam-in-quran-r2','maryam-in-quran','quran','The Qur’an — Ali Imran','3:42','https://quran.com/3/42','Primary source pointer; scholarly interpretation pending','pending','2');
