INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('truthfulness-in-sunnah','truthfulness-in-sunnah','Truthfulness and Honesty in the Sunnah','الصدق في السنة','Authentic transmitted teaching and Qur’anic context','sunnah','concept','Sahih al-Bukhari 6094 links truthfulness with righteousness and warns against habitual lying. Qur’an 9:119 also calls believers to be with the truthful. This dossier presents source-linked moral teaching while leaving complex questions of legal testimony, confidentiality and harm to qualified scholarly judgement.','Primary-source-linked introductory encyclopedia dossier.','honesty,truthfulness,truthful,what hadith discuss honesty,hadith honesty,truth in sunnah,lying in islam,being honest','Independent qualified Tafsir/Hadith scholarly review pending.','editorial_draft','published','93');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthfulness-in-sunnah-s1','truthfulness-in-sunnah','The principal Hadith','transmission','Sahih al-Bukhari 6094 contains a narration from Abdullah on how truthfulness leads toward righteousness while persistent lying leads toward wrongdoing. The full report establishes the source and wording for this moral teaching. Quranically does not substitute a fabricated quotation for the authenticated narration.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthfulness-in-sunnah-s2','truthfulness-in-sunnah','The Qur’anic theme','scripture','Surah At-Tawbah 9:119 calls believers to God-consciousness and to be among truthful people. It provides related Qur’anic context, while the detailed interpretation of the surrounding historical circumstances should be read in Tafsir.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthfulness-in-sunnah-s3','truthfulness-in-sunnah','Practice and character','practice','Honesty in ordinary life can include avoiding deliberate deception, correcting significant misstatements and keeping trustworthy records. These are everyday applications of the sources and should not be mistaken for verbatim statements from the Prophet ﷺ.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthfulness-in-sunnah-s4','truthfulness-in-sunnah','Questions needing a scholar','methodology','Situations involving legal evidence, safeguarding, privacy or competing duties may call for nuanced jurisprudential assessment. This article does not give legal advice or decide every exceptional circumstance; qualified source review and scholarly interpretation remain pending.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('truthfulness-in-sunnah-r1','truthfulness-in-sunnah','hadith','Sahih al-Bukhari — Good Manners','6094','https://sunnah.com/bukhari:6094','Primary source pointer; scholarly interpretation pending','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('truthfulness-in-sunnah-r2','truthfulness-in-sunnah','quran','The Qur’an — At-Tawbah','9:119','https://quran.com/9/119','Primary source pointer; scholarly interpretation pending','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('truthfulness-in-sunnah-r3','truthfulness-in-sunnah','hadith','HadeethEnc — Original publisher index','HadeethEnc 5504','https://hadeethenc.com/en/browse/hadith/5504','Primary source pointer; scholarly interpretation pending','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('backbiting-ghibah-sunnah','backbiting-ghibah-sunnah','Backbiting (Ghibah) in Qur’an and Sunnah','الغيبة في القرآن والسنة','Primary sources and ethical distinctions','sunnah','concept','Qur’an 49:12 warns against suspicion, spying and backbiting. Sahih Muslim 2589 records the Prophet ﷺ defining backbiting and distinguishing it from slander. This article gives source-grounded moral context without purporting to decide legal exceptions or interpersonal disputes.','Primary-source-linked introductory encyclopedia dossier.','backbiting,ghibah,gheebah,what is sunnah about backbiting,talking behind someone''s back,gossip in islam,back biting,slander and ghibah','Independent qualified Tafsir/Hadith scholarly review pending.','editorial_draft','published','94');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('backbiting-ghibah-sunnah-s1','backbiting-ghibah-sunnah','The Qur’anic prohibition','scripture','Surah Al-Hujurat 49:12 addresses suspicion, spying and backbiting. Its vivid warning about speaking of people behind their backs provides a direct scriptural foundation for the topic. Context and applications should be studied with qualified Tafsir.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('backbiting-ghibah-sunnah-s2','backbiting-ghibah-sunnah','A transmitted definition','transmission','In Sahih Muslim 2589 the Prophet ﷺ is reported to have explained backbiting as mentioning something about another person that the person would dislike, and distinguished this from false accusations. This is a primary authenticated-source starting point rather than an invented social-media definition.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('backbiting-ghibah-sunnah-s3','backbiting-ghibah-sunnah','Everyday ethical application','practice','Before sharing damaging information, a person can consider whether it is truthful, necessary, properly sourced and shared with the right audience. Avoiding ridicule or unjustified disclosure follows the ethical concern shown in the sources. These suggestions are editorial guidance rather than a new Hadith.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('backbiting-ghibah-sunnah-s4','backbiting-ghibah-sunnah','Important distinctions and exceptions','methodology','Scholarly discussions address contexts such as seeking protection, reporting misconduct, obtaining justice and seeking religious advice. This entry does not declare all such disclosures identical to gossip or provide legal rulings about individual accusations. Consult qualified scholarship for difficult cases.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('backbiting-ghibah-sunnah-r1','backbiting-ghibah-sunnah','quran','The Qur’an — Al-Hujurat','49:12','https://quran.com/49/12','Primary source pointer; scholarly interpretation pending','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('backbiting-ghibah-sunnah-r2','backbiting-ghibah-sunnah','hadith','Sahih Muslim — Virtue and Kinship','2589','https://sunnah.com/muslim:2589','Primary source pointer; scholarly interpretation pending','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('backbiting-ghibah-sunnah-r3','backbiting-ghibah-sunnah','hadith','Bulugh al-Maram — Comprehensive Book','Hadith 1538 (source: Muslim 2589)','https://sunnah.com/bulugh/16/59','Primary source pointer; scholarly interpretation pending','pending','3');
